def _index_review_lists(payloads: list[dict[str, object]]) -> dict[str, list[dict[str, object]]]:
    indexed: dict[str, list[dict[str, object]]] = {}
    for payload in payloads:
        reviews = _dict_items(payload.get("reviews"))
        if not reviews:
